/* ==========================================================================
   Zenbaki errealak · 4. DBH (aplikatuak) — diagnostic, guided practice,
   exercise bank and challenges from Santillana 4.º ESO Aplicadas unit 1 and
   Anaya 4.º ESO Aplicadas unit 3. Every closed answer is a single number;
   for a radical a√b the exercise asks for a. Exercises about intervals carry
   a LineSpec, drawn under the prompt by index.tsx.
   ========================================================================== */

type WithLine = { line?: LineSpec; solutionLine?: LineSpec }
export type RealsDiagnosticQuestion = DiagnosticQuestion & WithLine
export type RealsPracticeItem = PracticeItem & WithLine
export type RealsChallengeItem = ChallengeItem & WithLine
export type RealsExerciseItem = ExerciseItem & WithLine
export interface RealsExerciseSection {
    id: string
    title: LocalizedText
    items: RealsExerciseItem[]
}

/** Arabic writes the decimal point instead of the comma, so {,} becomes . there */
const say = (eu: string, es: string, ar: string, en: string): LocalizedText => ({ eu, es, en, ar: ar.replace(/\{,\}/g, '.') })
/** Same formula everywhere, decimal point in Arabic */
const same = (value: string): LocalizedText => ({ eu: value, es: value, en: value, ar: value.replace(/\{,\}/g, '.') })

